for(const th of [200,300,500,1000]){print('canary /search >'+th+'ms:',cs.filter(r=>r.ms>th).length,'stable:',ss.filter(r=>r.ms>th).length);}
const slow=cs.filter(r=>r.ms>200).sort((a,b)=>a.t-b.t);
print('slow canary /search times/ms:',slow.map(r=>r.t.toFixed(1)+'s:'+r.ms+'ms:'+r.status).join(' | '));
print('all canary >200ms any path:',canary.filter(r=>r.ms>200).length,'all stable >200ms:',stable.filter(r=>r.ms>200).length);
print('canary statuses:',JSON.stringify(canary.reduce((a,r)=>{a[r.status]=(a[r.status]||0)+1;return a;},{})));
print('stable statuses:',JSON.stringify(stable.reduce((a,r)=>{a[r.status]=(a[r.status]||0)+1;return a;},{})));

const sl=stable.filter(r=>r.ms>200).sort((a,b)=>b.ms-a.ms);
print('stable >200ms count', sl.length, '->', sl.map(r=>r.path+':'+r.ms+'ms').join(' | '));
['/browse','/search','/checkout'].forEach(p=>{
  const s=stable.filter(r=>r.path===p).map(r=>r.ms).sort((a,b)=>a-b);
  const c=canary.filter(r=>r.path===p).map(r=>r.ms).sort((a,b)=>a-b);
  print(p,'| stable p95',pct(s,95),'p99',pct(s,99),'max',s[s.length-1],'|| canary p95',pct(c,95),'p99',pct(c,99),'max',c[c.length-1]);
});
const cs=canary.filter(r=>r.path==='/search');
const ss=stable.filter(r=>r.path==='/search');
const cslow=cs.filter(r=>r.ms>400), sslow=ss.filter(r=>r.ms>400);
print('canary /search >400ms:', cslow.length, 'of', cs.length, '=', (100*cslow.length/cs.length).toFixed(2)+'%');
print('stable /search >400ms:', sslow.length, 'of', ss.length, '=', (100*sslow.length/ss.length).toFixed(2)+'%');
print('canary ALL >400ms:', canary.filter(r=>r.ms>400).length, 'stable ALL >400ms:', stable.filter(r=>r.ms>400).length);
for(let w=0;w<4;w++){const a=w*30,b=a+30;
  print('window',a+'-'+b+'s','canary /search slow',cslow.filter(r=>r.t>=a&&r.t<b).length,'of',cs.filter(r=>r.t>=a&&r.t<b).length,'| stable /search slow',sslow.filter(r=>r.t>=a&&r.t<b).length,'of',ss.filter(r=>r.t>=a&&r.t<b).length);}
const fast=cs.filter(r=>r.ms<=400).map(r=>r.ms).sort((a,b)=>a-b);
print('canary /search excluding slow tail: p50',pct(fast,50),'p95',pct(fast,95),'max',fast[fast.length-1]);
print('slow-tail ms range', Math.min(...cslow.map(r=>r.ms)), '-', Math.max(...cslow.map(r=>r.ms)));

