      "query": "const cs={},ss={};\ncanary.forEach(r=>cs[r.status]=(cs[r.status]||0)+1);\nstable.forEach(r=>ss[r.status]=(ss[r.status]||0)+1);\nprint('canary statuses '+JSON.stringify(cs)+' stable statuses '+JSON.stringify(ss));",
      "expect": "canary statuses {\"200\":2384} stable statuses {\"200\":7404}"
    },
    {
      "claim": "Canary /search has a slow tail absent from stable: 18 of 729 canary /search requests (2.47%) are slower than 400 ms, versus 0 of 2273 stable /search requests.",
      "query": "const cs=canary.filter(r=>r.path==='/search'), ss=stable.filter(r=>r.path==='/search');\nconst cslow=cs.filter(r=>r.ms>400), sslow=ss.filter(r=>r.ms>400);\nprint('canary /search slow '+cslow.length+'/'+cs.length+' ('+(100*cslow.length/cs.length).toFixed(2)+'%) stable /search slow '+sslow.length+'/'+ss.length);",
      "expect": "canary /search slow 18/729 (2.47%) stable /search slow 0/2273"
    },
    {
      "claim": "The canary slow tail sits at 633-656 ms, more than 3x the stable /search p95 of 193 ms, while canary /search excluding that tail has p95 190 ms vs stable 193 ms (a tail regression, not a general slowdown).",
      "query": "const cs=canary.filter(r=>r.path==='/search');\nconst tail=cs.filter(r=>r.ms>400).map(r=>r.ms), rest=cs.filter(r=>r.ms<=400).map(r=>r.ms);\nconst ss=stable.filter(r=>r.path==='/search').map(r=>r.ms);\nconst sp95=Math.round(pct(ss,95));\nprint('canary ex-tail p95 '+Math.round(pct(rest,95))+' | stable p95 '+sp95+' | tail '+Math.min.apply(null,tail)+'-'+Math.max.apply(null,tail)+'ms | tail min > 3x stable p95: '+(Math.min.apply(null,tail)>3*sp95));",
      "expect": "canary ex-tail p95 190 | stable p95 193 | tail 633-656ms | tail min > 3x stable p95: true"
    },
    {
      "claim": "The canary /search slow requests occur in every 30 s window (7, 2, 5, 4) while stable has none in any window, so the regression is sustained rather than a warmup artifact.",
      "query": "const w=[0,30,60,90];\nconst cc=w.map(s=>canary.filter(r=>r.path==='/search'&&r.t>=s&&r.t<s+30&&r.ms>400).length);\nconst sc=w.map(s=>stable.filter(r=>r.path==='/search'&&r.t>=s&&r.t<s+30&&r.ms>400).length);\nprint('canary slow by window '+cc.join(',')+' stable slow by window '+sc.join(','));",
      "expect": "canary slow by window 7,2,5,4 stable slow by window 0,0,0,0"
    },
    {
      "claim": "The regression is confined to /search: no canary request on any other path exceeded 400 ms (and no stable request on any other path did either).",
      "query": "const c=canary.filter(r=>r.path!=='/search'&&r.ms>400).length;\nconst s=stable.filter(r=>r.path!=='/search'&&r.ms>400).length;\nprint('canary non-search >400ms '+c+' stable non-search >400ms '+s);",
      "expect": "canary non-search >400ms 0 stable non-search >400ms 0"
    }
  ]
}

